targets.expr:
last_over_time(
  (
    (
      sum by (service_basename) (
        label_replace(
          rate(istio_requests_total{
            reporter="destination",
            request_path!~"/metrics|/|/events|.*/readyz|.*/livez|.*/healthz|.*/openapi*|.*/metrics",
            response_code!~"[45].*",
            grpc_response_status!~"[1-9].+"
          }[$__rate_interval]),
          "service_basename", "$1", "destination_service", "([a-z-]*[a-z]).*"
        )
      ) 
      / 
      (
        sum by (service_basename) (
          label_replace(
            rate(istio_requests_total{
              reporter="destination",
              request_path!~"/metrics|/|/events|.*/readyz|.*/livez|.*/healthz|.*/openapi*|.*/metrics"
            }[$__rate_interval]),
            "service_basename", "$1", "destination_service", "([a-z-]*[a-z]).*"
          )
        ) > 0
      )
    ) * 100
  )[2h:]
)
